import {StreamParser,hex,demoRecords,decode} from './protocol.mjs';
const $=id=>document.getElementById(id);let records=[], selected=null,port=null,reader=null,readTask=null,closing=false,scheduled=false,mode='未接続';
let parser=new StreamParser(add);
function notice(s){$('notice').textContent=s;}
function add(r){records.push(r);if(records.length>2000)records.shift();selected??=r;if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;render();});}}
function reset(){records=[];selected=null;parser=new StreamParser(add);render();}
function render(){
 $('status').textContent=mode;$('count').textContent=records.length;$('errors').textContent=records.filter(x=>!x.ok).length;$('drops').textContent=records.at(-1)?.dropped??0;$('transport').textContent=parser.errors;
 const filter=$('filter').value, list=records.filter(x=>filter==='errors'?!x.ok:filter==='noack'?x.name!=='GoodCRC':true);
 const frag=document.createDocumentFragment();for(const r of list.slice().reverse()) {const tr=document.createElement('tr');tr.tabIndex=0;if(r===selected)tr.className='active';for(const s of [r.seq,(r.ticks/27e6).toFixed(6),r.sop,r.name,r.kind>=5?'RESET':r.ok?'OK':'ERROR']){const td=document.createElement('td');td.textContent=s;tr.append(td);}tr.lastChild.className=r.ok?'good':'bad';const pick=()=>{selected=r;render();};tr.onclick=pick;tr.onkeydown=e=>{if(e.key==='Enter')pick();};frag.append(tr);} $('rows').replaceChildren(frag);$('empty').hidden=list.length>0;
 $('selected').textContent=selected?.name??'パケットを選択';const d=$('detail');d.replaceChildren();if(!selected){d.textContent='一覧の行を選ぶと、ヘッダとデータオブジェクトを確認できます。';return;}
 const r=selected,dl=document.createElement('dl');for(const [k,v] of [['SOP',r.sop],['Header','0x'+r.header.toString(16).padStart(4,'0')],['Message ID',r.messageId],['PD revision',r.revision],['Role',r.role],['Objects',r.n],['Status',r.problems.join(' / ')||'OK']]) {const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd);}d.append(dl);
 const pre=document.createElement('pre');pre.textContent=hex(r.raw)||'(ordered set only)';d.append(pre);
 if(r.extended){const p=document.createElement('p');p.textContent='Extended header: '+JSON.stringify(r.extended);d.append(p);}
 for(const o of r.objects){const el=document.createElement('div');el.className='obj';const b=document.createElement('b');b.textContent=`DO${o.index} · 0x${o.hex}`;const p=document.createElement('div');p.textContent=o.detail||'Raw data object';el.append(b,p);d.append(el);}
}
async function readLoop(p){try{while(p.readable&&!closing){reader=p.readable.getReader();try{while(!closing){const {value,done}=await reader.read();if(done)break;if(value){parser.feed(value);if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;render();});}}}}finally{reader.releaseLock();reader=null;}}}catch(e){notice('受信を終了しました: '+e.message);}finally{try{await p.close();}catch{}port=null;mode='未接続';$('connect').textContent='シリアルに接続';$('baud').disabled=false;$('demo').disabled=false;$('import').disabled=false;render();}}
$('connect').onclick=async()=>{const b=$('connect');b.disabled=true;try{if(port){closing=true;if(reader)await reader.cancel();await readTask;}else{if(!navigator.serial)throw Error('このブラウザではWeb Serialが使えません。Chrome / EdgeでHTTPSまたはlocalhostを開いてください。');const p=await navigator.serial.requestPort();await p.open({baudRate:Number($('baud').value),dataBits:8,stopBits:1,parity:'none',flowControl:'none',bufferSize:65536});port=p;closing=false;reset();mode='LIVE · CC';b.textContent='切断';$('baud').disabled=true;$('demo').disabled=true;$('import').disabled=true;notice('受信中 · UARTへの書き込みは行いません。');render();readTask=readLoop(p);}}catch(e){notice(e.message);}finally{b.disabled=false;}};
$('demo').onclick=()=>{reset();mode='DEMO';for(const r of demoRecords())parser.feed(r);notice('デモデータを表示しています。実機の受信結果ではありません。');render();};
$('clear').onclick=()=>{reset();};$('filter').onchange=render;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'tn9k-pd-v1',mode,records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='usb-pd-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('ログは10 MB以下にしてください。');if(f.name.endsWith('.json')){const j=JSON.parse(await f.text());if(j.format!=='tn9k-pd-v1'||!Array.isArray(j.records))throw Error('未対応のログ形式');const valid=j.records.slice(-2000).map(r=>{if(!Array.isArray(r.raw)||r.raw.length>34||r.raw.some(x=>!Number.isInteger(x)||x<0||x>255)||![r.kind,r.flags,r.seq,r.ticks,r.dropped].every(Number.isInteger)||r.kind<0||r.kind>6)throw Error('不正なレコード');return decode(r);});reset();valid.forEach(add);}else{reset();const bytes=new Uint8Array(await f.arrayBuffer());for(let i=0;i<bytes.length;i+=4096)parser.feed(bytes.slice(i,i+4096));}mode='FILE';notice('ファイルから読み込みました: '+f.name);render();}catch(e){notice('読み込みエラー: '+e.message);}finally{$('import').value='';}};
if(!navigator.serial)notice('この環境ではWeb Serialが利用できません。デモとログ表示は使用できます。実機接続はChrome / Edgeで開いてください。');render();
